partner_tag = env.ref("x_sponsor.res_partner_category_sponsor", raise_if_not_found=False)
if partner_tag: partners = env["res.partner"].search([("category_id", "=", partner_tag.id)]) today = datetime.date.today()
values_to_create = [] for contract in records: for partner in partners: values_to_create.append({ "x_partner_id": partner.id, "x_sponsor_contract_id": contract.id, "x_user_id": False, "x_date": today, }) env["x_sponsor.sponsor"].create(values_to_create)

