mapping = { "draft": env.ref("x_sponsor.sponsor_stage_new", raise_if_not_found=False), "sent": env.ref("x_sponsor.sponsor_stage_sent", raise_if_not_found=False), "cancelled": env.ref("x_sponsor.sponsor_stage_cancel", raise_if_not_found=False), "done": env.ref("x_sponsor.sponsor_stage_done", raise_if_not_found=False), }
for status, stage in mapping.items(): env["x_sponsor.sponsor"].search([("x_sponsor_contract_id", "in", records.ids), ("x_stage_id", "=", stage.id)]).write({"x_status": status})
